(4, 'mattabedin', '12bce374e7be15142e8172f668da00d8', 'Matt', 'subadmin', NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2020-08-20 21:33:54', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, NULL, NULL, NULL, 0, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
INSERT INTO `tbl_sitecontent` (`id`, `ckey`, `code`, `full_code`) VALUES
(1, 'product_detail', 'a:5:{s:10:\"page_title\";s:14:\"Product Detail\";s:16:\"meta_description\";s:14:\"product detail\";s:13:\"meta_keywords\";s:14:\"product detail\";s:14:\"secure_payment\";s:2392:\"<p style=\"margin-bottom: 15px;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\">At the moment we offer the following different payment options:</p><ul style=\"margin-right: 0px; margin-bottom: 10px; margin-left: 0px; padding: 0px 20px 0px 0px; list-style-position: inside;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\"><li>Ideal</li><li>Paypal</li><li>Appel pay</li><li>Mastercard</li><li>Visa</li><li>American express</li><li>FrancescoMaccardo giftcard/ discount</li></ul><p style=\"margin-bottom: 15px;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\">Pay attention:</p><ul style=\"margin-right: 0px; margin-bottom: 10px; margin-left: 0px; padding: 0px 20px 0px 0px; list-style-position: inside;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\"><li>- You can only use one promotional code per order, unless stated otherwise</li><li>- Promotion codes cannot be used in conjunction with other existing promotions or offers.</li><li>- In the case of returns, the value of the promotional code will be divided over the ordered items.</li><li>- Vouchers for the newsletter (10%) and birthdays (15%):</li><li>- Can be used on sale items.</li><li>- Can be used in our online webshop and our physical FrancescoMaccardo webshop.</li></ul><p style=\"margin-bottom: 15px;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\">When you select PayPal as your payment method, you will be automatically redirected to the PayPal website. If you have a PayPal account, you can log in with your user details to confirm the payment.</p><p style=\"margin-bottom: 15px;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\">If you don\'t have a PayPal account, you can create one and proceed with the payment.</p><p style=\"margin-bottom: 15px;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\">Refunds on returns will be made to the registered PayPal account respectively.</p><p style=\"margin-bottom: 15px;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\">Important information about payment:</p><p style=\"margin-bottom: 15px;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\">Credit and debit cards are not charged until the order is shipped.</p><p style=\"margin-bottom: 0px;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\">For your security, your billing name and address must match that of the credit card used for payment. We reserve the right to cancel orders that do not meet these requirements.</p>\";s:15:\"return_shipping\";s:1686:\"<ul style=\"margin-right: 0px; margin-bottom: 10px; margin-left: 0px; padding: 0px 20px 0px 0px; list-style-position: inside;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\"><li style=\"\">WE GLADLY ACCEPT RETURNS AND EXCHANGES</li><li style=\"\">Just contact me within: 14 days of delivery</li><li style=\"\">Ship items back to me within: 30 days of delivery</li><li style=\"\">We have a 30-day return policy, which means you have 30 days after receiving your item to request a return.</li><li style=\"\">To be eligible for a return, your item must be in the same condition that you received it, unworn or unused, with tags, and in its original packaging. You’ll also need the receipt or proof of purchase.</li><li style=\"\">To start a return, you can contact us at Info@francescomaccaredo.com If your return is accepted, we’ll send you a return shipping label, as well as instructions on how and where to send your package. Items sent back to us without first requesting a return will not be accepted.</li></ul><p style=\"margin-bottom: 15px;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\">ESTIMATED SHIPPING TIMES</p><ul style=\"margin-right: 0px; margin-bottom: 10px; margin-left: 0px; padding: 0px 20px 0px 0px; list-style-position: inside;\" abeezee=\"\" regular\";=\"\" font-size:=\"\" 11.2px;\"=\"\"><li style=\"\">North America : 2 - 7 business days</li><li style=\"\">Europe : 2 - 7 business days</li><li style=\"\">Australia, New Zealand and Oceania : 3 - 7 business days</li><li style=\"\">Asia Pacific : 3 - 15 business days</li><li style=\"\">I\'ll do my best to meet these shipping estimates, but can\'t guarantee them. Actual delivery time will depend on the shipping method you choose.</li></ul>\";}', NULL),
(2, 'signup', 'a:11:{s:10:\"page_title\";s:7:\"Sign up\";s:16:\"meta_description\";s:7:\"Sign up\";s:13:\"meta_keywords\";s:7:\"Sign up\";s:14:\"signup_heading\";s:7:\"Sign up\";s:17:\"signup_short_desc\";s:110:\"Register for free and enjoy all our benefits. With your information you can log in and log out in our webshop.\";s:13:\"signup_detail\";s:245:\"<ul style=\"margin-left:0px; margin-right:0px\">\r\n	<li>Save payment details for future use</li>\r\n	<li>Change details</li>\r\n	<li>Change address</li>\r\n	<li>View your orders</li>\r\n	<li>Contact us on live chat</li>\r\n	<li>Track your order</li>\r\n</ul>\r\n\";s:13:\"login_heading\";s:7:\"Sign in\";s:16:\"login_short_desc\";s:36:\"Sign in your Hippolook account here.\";s:14:\"forgot_heading\";s:15:\"Forgot Password\";s:18:\"forgot_sub_heading\";s:19:\"Reset your password\";s:17:\"forgot_short_desc\";s:54:\"We will send you verified email to reset your password\";}', NULL),
(3, 'reset', 'a:3:{s:7:\"heading\";s:14:\"Reset password\";s:10:\"short_desc\";s:38:\"Enter a new password for your account.\";s:5:\"image\";s:52:\"bc6dc48b743dc5d013b1abaebd2faed2_1577355238_2644.svg\";}', NULL),
(8, 'email_verify', 'a:2:{s:15:\"everify_heading\";s:18:\"Email Verification\";s:14:\"everify_detail\";s:260:\"<p>Please verify your email address, We’ve sent a verify email to your email address. If you don’t see the email, check your spam folder. If you didn\'t get email click on resend email link, or if you want to change email address click the link below.</p>\r\n\";}', NULL),
(9, 'search', '', NULL),
(10, 'phone_verify', 'a:2:{s:15:\"pverify_heading\";s:18:\"Phone Verification\";s:14:\"pverify_detail\";s:289:\"<p>We are going to send you a text message for Phone verification if you want to verify your phone number, Please make sure your phone number is correct before verification. Click the link below to verify your phone number or if you want to change Phone Number click the link below .</p>\r\n\";}', NULL),
